"""Review 21 source units and distinguish pretraining/DEC/IDEC paths."""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'tools'))
from edit_chapter import ROOT,load,save,transform,sections,digest
c=load();rel='03-clustering/cl-deep.md'
pairs=[
('Как self-training изменяет представление и когда усиливает собственные ошибки?','Как самообучение изменяет представление и когда усиливает собственные ошибки?'),
('В [DEC](https://proceedings.mlr.press/v48/xieb16.html) сначала обучают автокодировщик восстанавливать вход и инициализируют центры в скрытом пространстве.',
 'В [DEC](https://proceedings.mlr.press/v48/xieb16.html) сначала обучают **автокодировщик**: кодировщик $f_\\theta$ переводит вход $x_i\\in\\mathbb R^D$ в скрытый вектор $z_i\\in\\mathbb R^d$, а декодер $g_\\phi$ восстанавливает вход из этого вектора. По полученным представлениям инициализируют K центров, в исходной работе — K-Means.'),
('Параметр $\\nu$ задаёт форму ядра.',
 'Здесь i=1,…,n — объекты, j=1,…,K — группы; центры $\\mu_j$ имеют ту же ширину d, что и $z_i$. Параметр $\\nu>0$ задаёт число степеней свободы ядра Стьюдента. Для одной строки сумма q равна 1, но это назначение в выбранной модели, а не автоматически откалиброванная вероятность смыслового класса. При $z=0$, центрах 0 и 2, $\\nu=1$ ненормированные веса равны 1 и 1/5, поэтому $q=(5/6,1/6)$.'),
('Во время одного обновления p фиксировано, затем периодически пересчитывается.',
 'Кластерная ошибка — расхождение KL между вспомогательной целью p и текущим q. Во время одного обновления p фиксировано: через его построение не проводят производную этого шага. Затем p периодически пересчитывается. Порядок пересчёта и область оценки частот должны входить в протокол.'),
('Уверенность выросла без нового свидетельства.',
 'Неравные частоты могут изменить даже предпочтительную группу. Для $q=(0.6,0.4)$ и общих частот $f=(9,1)$ получаем $q^2/f=(0.04,0.16)$, поэтому $p=(0.2,0.8)$. Такие частоты должны относиться ко всему выбранному набору, а не только к одному объекту. Если объект единственный, $f=q$ и цель совпадает с q.\n\nУверенность выросла в симметричном примере без нового свидетельства.'),
('Декодер g заставляет представление хранить сведения об исходном x.',
 'В этой записи $\\theta$ — параметры кодировщика, $\\phi$ — декодера, n — число объектов, $\\gamma\\ge0$ — вес кластерной части. Декодер g заставляет представление хранить сведения об исходном x.'),
('Если два представления имеют одинаковую кластерную ошибку,',
 '![IDEC: кластерная и восстанавливающая ветви общего представления](<../оформление/course/cl-idec-branches.svg>)\n\nНа схеме скрытый z передаётся и в декодер, и в расчёт q по центрам. Исходный x является целью восстановления; фиксированное p — целью кластерной части. Суммарная ошибка обновляет кодировщик, декодер и центры, тогда как в основной фазе DEC ветви декодера нет.\n\nЕсли два представления имеют одинаковую кластерную ошибку,'),
('Составьте two-stage', 'Составьте двухэтапное')]
def op(s):
    for before,after in pairs:
        if before not in s:
            if before=='Составьте two-stage':continue
            raise ValueError(before)
        s=s.replace(before,after)
    return s
transform(rel,op,'Сверены 21 исходная единица и первичные DEC/IDEC; определены автокодировщик, формы, фиксированное p, неравные частоты и разные фазы обучения.',c);save(c)
groups={
'Совместное обучение и собственные цели':'''5e17c55e3f7d5d4eda ed7c8cd5384a791c38''',
'Назначения Student-t и усиленное распределение':'''74dd505432c9488faa 4f1893a7f71f4fd9b8 eec102cb1986eabace 9f4e562a1db2a376ed 1bb02a0377e446d194''',
'Два числовых случая и риск коллапса':'''b5ead5ef8ba6836ad9 71b86995b4dc2fe870 5cc74e3641361cf5e8 14df28fc7ef3766ba8 026d5f025abbd09b08 7fab3def64b7de6b3f''',
'IDEC: сохранить восстановление':'''0b204a2e32eb18bf1f c90987532e47298ff5 d8f266e79c4ceb43ad 571baa68fb9fe1d36a b73fd4dc810f349b40''',
'Самостоятельная практика':'''cb5d443166e60aa638 7e739379c0a8cc5c15 049f08d5ab6539affb'''}
dest={ident:[title] for title,ids in groups.items() for ident in ids.split()}
dest['7e739379c0a8cc5c15']+=['Совместное обучение и собственные цели','Назначения Student-t и усиленное распределение','IDEC: сохранить восстановление']
dest['7fab3def64b7de6b3f']+=['Совместное обучение и собственные цели','Назначения Student-t и усиленное распределение','IDEC: сохранить восстановление']
parts=sections((ROOT/rel).read_text(encoding='utf8'));units=[u for u in c['units'] if u.get('chapter')=='cl-deep' and not u.get('provenance_only')]
assert set(dest)=={u['id'] for u in units}
for u in units:
    targets=[]
    for i,title in enumerate(dest[u['id']]):
        a,b,body=parts[title];key=u['anchor'] if i==0 else f"t-cl-deep-{u['id']}-{i}"
        c['spans'][key]={'path':rel,'start_line':a,'end_line':b,'sha256':digest(body),'destination_section':title,'status':'revised','review_status':'verified','rationale':'Исходная единица прочитана; сверены фазы DEC/IDEC, формулы q/p/KL, числа, коллапс и ограничения восстановления. Повторные случаи объединены с отдельными целями.','evidence':'editorial/review-evidence.md#deep-clustering'}
        targets.append(key)
    u.update(targets=targets,status='semantic-reviewed',action='объединить с сохранением нюансов')
